const W = api.w, H = api.h, t = api.t, TAU = Math.PI * 2;
const A = p.intensity;
const cx = (W - 1) / 2, cy = (H - 1) / 2;
const rx = Math.max(3, W * 0.40), ry = Math.max(4, H * 0.46);
const breathe = 0.5 + 0.5 * Math.sin(TAU * t);

// oval field. wider than before so it reads as a doorway, not an egg.
// no dark ring: the edge is a soft purple falloff that thins into the sheet.
for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    const dx = (x - cx) / rx, dy = (y - cy) / ry;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d > 1.02) continue;
    const ang = Math.atan2((y - cy) / ry, (x - cx) / rx);
    // bands sweep inward and around, so the interior is always moving
    const swirl = 0.5 + 0.5 * Math.sin(TAU * (d * 2.2 - t + ang / TAU));
    const edge = d > 0.82 ? (1.02 - d) / 0.20 : 1;
    const f = 1 - d;
    // 3 and 4 are the mid purples, 2 lifts the brightest band so it glows
    const c = swirl > 0.80 ? 2 : swirl > 0.52 ? 3 : 4;
    const a = (0.30 + 0.26 * f + 0.30 * swirl + 0.08 * breathe) * edge * A;
    api.px(x, y, c, a);
  }
}

// dark core: a narrow vertical void down the middle, pulsing
for (let y = 0; y < H; y++) {
  const dy = (y - cy) / (ry * 0.90);
  if (Math.abs(dy) >= 1) continue;
  const v = Math.sqrt(1 - dy * dy);
  const cw = Math.round(v * rx * 0.44 * p.core * (0.84 + 0.16 * breathe));
  if (cw > 0) api.rect(Math.round(cx - cw / 2), y, cw, 1, 5, (0.50 + 0.16 * breathe) * A);
}

// rising threads, spread across the full width so the whole oval churns
const n = Math.max(1, Math.round(p.threads));
for (let i = 0; i < n; i++) {
  const r = api.rnd(i), r2 = api.rnd(i + 91), r3 = api.rnd(i + 311);
  const cyc = Math.max(1, Math.round(p.drift) * (1 + Math.floor(r2 * 2)));
  const ph = (t * cyc + r) % 1;
  const len = 4 + Math.round(6 * r3);
  const wob = Math.sin(TAU * (t + r)) * p.warp * (0.4 + r2);
  const bx = Math.round(cx + (r * 2 - 1) * rx * 0.86 + wob);
  for (let s = 0; s < len; s++) {
    const y = cy + ry - ((ph * (ry * 2) + s) % (ry * 2));
    const yy = Math.round(y);
    const dx = (bx - cx) / rx, dy = (yy - cy) / ry;
    if (dx * dx + dy * dy > 0.94) continue;
    const f = 1 - s / len;
    const c = f > 0.76 ? 1 : f > 0.42 ? 2 : 3;
    api.px(bx, yy, c, (0.22 + 0.60 * f) * A);
  }
}

// bright motes riding up the throat
for (let k = 0; k < 10; k++) {
  const r = api.rnd(k + 700), r2 = api.rnd(k + 811), r3 = api.rnd(k + 907);
  const ph = (t * (1 + Math.floor(r3 * 3)) + r) % 1;
  const gy = Math.round(cy + ry - ph * (ry * 2));
  const gx = Math.round(cx + (r2 * 2 - 1) * rx * 0.66 + Math.sin(TAU * (t + r2)) * 1.2);
  const dx = (gx - cx) / rx, dy = (gy - cy) / ry;
  if (dx * dx + dy * dy > 0.88) continue;
  const fade = 0.35 + 0.65 * Math.sin(Math.PI * ph);
  api.px(gx, gy, 0, (0.30 + 0.55 * fade) * A);
  if (fade > 0.7) api.px(gx, gy + 1, 1, 0.34 * fade * A);
}
